using System;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class BundleResultsTests{static int n;static void C(bool b,string m){n++;if(!b)throw new Exception(m);}static System.Collections.Generic.IEnumerable<Control> Walk(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in Walk(x))yield return y;}}[STAThread]static int Main(){try{foreach(bool dark in new[]{false,true})foreach(int count in new[]{1,30})using(var f=new BundleDifferencesForm(Enumerable.Range(0,count).Select(i=>new BundleDifferenceItem{Path="file"+i+".exe",State="Отсутствует — скачать",Allowed=i!=1}).ToArray())){f.SetTheme(dark,false);f.Show();for(int i=0;i<8;i++)Application.DoEvents();var all=Walk(f).ToArray();var g=all.OfType<ServiceGrid>().Single();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"results-"+(dark?"dark":"light")+"-"+count+".png"));}var buttons=all.OfType<BrandButton>().Where(b=>new[]{"Выбрать всё","Снять выбор","Применить"}.Contains(b.Text)).ToArray();C(buttons.Length==3,"Three buttons");C(buttons.Max(b=>b.Width)-buttons.Min(b=>b.Width)<=1,"Equal widths");C(buttons.Select(b=>b.Height).Distinct().Count()==1,"Equal heights");C(g.TouchScrollingEnabled,"Touch enabled");C(g.Columns[1].HeaderText=="Файлы","Files header");C(Math.Abs(buttons.Single(b=>b.Text=="Применить").PointToScreen(new Point(buttons[2].Width,0)).X-g.PointToScreen(new Point(g.Width,0)).X)<=1,"Right edge matches table");buttons.Single(b=>b.Text=="Выбрать всё").PerformClick();C(Convert.ToBoolean(g.Rows[0].Cells[0].Value),"Select all");if(count>1)C(!Convert.ToBoolean(g.Rows[1].Cells[0].Value),"Forbidden stays unchecked");buttons.Single(b=>b.Text=="Снять выбор").PerformClick();C(g.Rows.Cast<DataGridViewRow>().All(r=>!Convert.ToBoolean(r.Cells[0].Value)),"Clear all");if(count==1)C(g.Height<g.Parent.Height,"No extra painted viewport");}Console.WriteLine("PASS: "+n+" results layout/selection/touch checks, both themes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}